// QoP represents ASN.1 SEQUENCE
type QoP struct {
	Horacc           int64
	Veracc           *int64
	MaxLocAge        *int64
	Delay            *int64
	Ver2ResponseTime *int64
}

func (v *QoP) EncodeUPER(w *uper.BitWriter) error {
	hasExt := v.Ver2ResponseTime != nil
	w.WriteBit(hasExt)
	w.WriteBit(v.Veracc != nil)
	w.WriteBit(v.MaxLocAge != nil)
	w.WriteBit(v.Delay != nil)
	if err := w.WriteConstrainedInt(int64(v.Horacc), 0, 127); err != nil {
		return err
	}
	if v.Veracc != nil {
		if err := w.WriteConstrainedInt(int64((*v.Veracc)), 0, 127); err != nil {
			return err
		}
	}
	if v.MaxLocAge != nil {
		if err := w.WriteConstrainedInt(int64((*v.MaxLocAge)), 0, 65535); err != nil {
			return err
		}
	}
	if v.Delay != nil {
		if err := w.WriteConstrainedInt(int64((*v.Delay)), 0, 7); err != nil {
			return err
		}
	}
	if hasExt {
		// Determine highest present extension addition
		numAdditions := 0
		if v.Ver2ResponseTime != nil {
			numAdditions = 1
		}
		if numAdditions > 0 {
			if err := w.WriteNormallySmallNonNegativeWholeNumber(uint64(numAdditions - 1)); err != nil {
				return err
			}
			if 0 < numAdditions {
				w.WriteBit(v.Ver2ResponseTime != nil)
			}
			if 0 < numAdditions && v.Ver2ResponseTime != nil {
				subW := uper.NewBitWriter()
				if err := subW.WriteConstrainedInt(int64((*v.Ver2ResponseTime)), 1, 128); err != nil {
					return err
				}
				if err := w.WriteOpenType(subW.Bytes()); err != nil {
					return err
				}
			}
		}
	}
	return nil
}

func (v *QoP) DecodeUPER(r *uper.BitReader) error {
	hasExt, err := r.ReadBit()
	if err != nil {
		return err
	}
	present_Veracc, err := r.ReadBit()
	if err != nil {
		return err
	}
	present_MaxLocAge, err := r.ReadBit()
	if err != nil {
		return err
	}
	present_Delay, err := r.ReadBit()
	if err != nil {
		return err
	}
	{
		decodedVal, err := r.ReadConstrainedInt(0, 127)
		if err != nil {
			return err
		}
		v.Horacc = decodedVal
	}
	if present_Veracc {
		var val int64
		{
			decodedVal, err := r.ReadConstrainedInt(0, 127)
			if err != nil {
				return err
			}
			val = decodedVal
		}
		v.Veracc = &val
	}
	if present_MaxLocAge {
		var val int64
		{
			decodedVal, err := r.ReadConstrainedInt(0, 65535)
			if err != nil {
				return err
			}
			val = decodedVal
		}
		v.MaxLocAge = &val
	}
	if present_Delay {
		var val int64
		{
			decodedVal, err := r.ReadConstrainedInt(0, 7)
			if err != nil {
				return err
			}
			val = decodedVal
		}
		v.Delay = &val
	}
	if hasExt {
		kMinus1, err := r.ReadNormallySmallNonNegativeWholeNumber()
		if err != nil {
			return err
		}
		numExt := int(kMinus1) + 1
		extPresence := make([]bool, numExt)
		for i := 0; i < numExt; i++ {
			bit, err := r.ReadBit()
			if err != nil {
				return err
			}
			extPresence[i] = bit
		}
		for i := 0; i < numExt; i++ {
			if extPresence[i] {
				openBytes, err := r.ReadOpenType()
				if err != nil {
					return err
				}
				subR := uper.NewBitReader(openBytes)
				_ = subR
				switch i {
				case 0:
					var val int64
					{
						decodedVal, err := subR.ReadConstrainedInt(1, 128)
						if err != nil {
							return err
						}
						val = decodedVal
					}
					v.Ver2ResponseTime = &val
				default:
					// Ignore unknown future extension addition
				}
			}
		}
	}
	return nil
}

