const (
	PosPayLoadChoice_None            PosPayLoadChoice = 0
	PosPayLoadChoice_RrcPayload      PosPayLoadChoice = 1
	PosPayLoadChoice_RrlpPayload     PosPayLoadChoice = 2
	PosPayLoadChoice_MultiPosPayload PosPayLoadChoice = 3
)

// PosPayLoad represents ASN.1 CHOICE
type PosPayLoad struct {
	Choice          PosPayLoadChoice
	RrcPayload      *[]byte
	RrlpPayload     *[]byte
	MultiPosPayload *MultiPosPayLoad
}

func (v *PosPayLoad) EncodeUPER(w *uper.BitWriter) error {
	switch v.Choice {
	case PosPayLoadChoice_RrcPayload:
		w.WriteBit(false)
		if err := w.WriteConstrainedInt(0, 0, 2); err != nil {
			return err
		}
		if v.RrcPayload == nil {
			return fmt.Errorf("choice alternative RrcPayload is nil")
		}
		if err := w.WriteOctetString([]byte((*v.RrcPayload)), 1, 8192); err != nil {
			return err
		}
		return nil
	case PosPayLoadChoice_RrlpPayload:
		w.WriteBit(false)
		if err := w.WriteConstrainedInt(1, 0, 2); err != nil {
			return err
		}
		if v.RrlpPayload == nil {
			return fmt.Errorf("choice alternative RrlpPayload is nil")
		}
		if err := w.WriteOctetString([]byte((*v.RrlpPayload)), 1, 8192); err != nil {
			return err
		}
		return nil
	case PosPayLoadChoice_MultiPosPayload:
		w.WriteBit(false)
		if err := w.WriteConstrainedInt(2, 0, 2); err != nil {
			return err
		}
		if v.MultiPosPayload == nil {
			return fmt.Errorf("choice alternative MultiPosPayload is nil")
		}
		if err := (*v.MultiPosPayload).EncodeUPER(w); err != nil {
			return err
		}
		return nil
	default:
		return fmt.Errorf("no choice alternative selected for PosPayLoad")
	}
}

func (v *PosPayLoad) DecodeUPER(r *uper.BitReader) error {
	isExt, err := r.ReadBit()
	if err != nil {
		return err
	}
	if !isExt {
		idx, err := r.ReadConstrainedInt(0, 2)
		if err != nil {
			return err
		}
		switch idx {
		case 0:
			v.Choice = PosPayLoadChoice_RrcPayload
			var val []byte
			{
				decodedBytes, err := r.ReadOctetString(1, 8192)
				if err != nil {
					return err
				}
				val = decodedBytes
			}
			v.RrcPayload = &val
		case 1:
			v.Choice = PosPayLoadChoice_RrlpPayload
			var val []byte
			{
				decodedBytes, err := r.ReadOctetString(1, 8192)
				if err != nil {
					return err
				}
				val = decodedBytes
			}
			v.RrlpPayload = &val
		case 2:
			v.Choice = PosPayLoadChoice_MultiPosPayload
			var val MultiPosPayLoad
			if err := val.DecodeUPER(r); err != nil {
				return err
			}
			v.MultiPosPayload = &val
		default:
			return fmt.Errorf("unknown choice root index %d for PosPayLoad", idx)
		}
		return nil
	}
	extIdx, err := r.ReadNormallySmallNonNegativeWholeNumber()
	if err != nil {
		return err
	}
	openBytes, err := r.ReadOpenType()
	if err != nil {
		return err
	}
	subR := uper.NewBitReader(openBytes)
	_ = subR
	switch extIdx {
	default:
		// Ignore unsupported future extension choice
	}
	return nil
}

// MultiPosPayLoad represents ASN.1 SEQUENCE
type MultiPosPayLoad struct {
	LPPPayload    *MultiPosPayLoadLPPPayload
	Tia801Payload *MultiPosPayLoadTia801Payload
}

func (v *MultiPosPayLoad) EncodeUPER(w *uper.BitWriter) error {
	w.WriteBit(false)
	w.WriteBit(v.LPPPayload != nil)
	w.WriteBit(v.Tia801Payload != nil)
	if v.LPPPayload != nil {
		if err := (*v.LPPPayload).EncodeUPER(w); err != nil {
			return err
		}
	}
	if v.Tia801Payload != nil {
		if err := (*v.Tia801Payload).EncodeUPER(w); err != nil {
			return err
		}
	}
	return nil
}

func (v *MultiPosPayLoad) DecodeUPER(r *uper.BitReader) error {
	hasExt, err := r.ReadBit()
	if err != nil {
		return err
	}
	if hasExt {
		kMinus1, err := r.ReadNormallySmallNonNegativeWholeNumber()
		if err != nil {
			return err
		}
		for i := 0; i < int(kMinus1)+1; i++ {
			bit, err := r.ReadBit()
			if err != nil {
				return err
			}
			if bit {
				if _, err := r.ReadOpenType(); err != nil {
					return err
				}
			}
		}
	}
	present_LPPPayload, err := r.ReadBit()
	if err != nil {
		return err
	}
	present_Tia801Payload, err := r.ReadBit()
	if err != nil {
		return err
	}
	if present_LPPPayload {
		var val MultiPosPayLoadLPPPayload
		if err := val.DecodeUPER(r); err != nil {
			return err
		}
		v.LPPPayload = &val
	}
	if present_Tia801Payload {
		var val MultiPosPayLoadTia801Payload
		if err := val.DecodeUPER(r); err != nil {
			return err
		}
		v.Tia801Payload = &val
	}
	return nil
}

