	{
		decodedVal, err := r.ReadConstrainedInt(0, 65535)
		if err != nil {
			return err
		}
		v.Length = decodedVal
	}
	if err := v.Version.DecodeUPER(r); err != nil {
		return err
	}
	if err := v.SessionID2.DecodeUPER(r); err != nil {
		return err
	}
